<script module lang="ts">
/**
 * Trail of links from the root to the current page (`design/components/breadcrumbs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/breadcrumbs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, agentMember, agentPress, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/breadcrumbs.module.css'
import Button from '../controls/Button.svelte'
import Menu from '../overlays/Menu.svelte'

export interface BreadcrumbItem {
  label: string
  href?: string
  onSelect?: () => void
}

export interface BreadcrumbsProps {
  /**
   * Opens the overflow on mount, for galleries and tests only.
   */
  defaultOpen?: boolean
  /**
   * The last item is the current page; its `href`/`onSelect` are ignored.
   */
  items: BreadcrumbItem[]
  /**
   * The landmark's accessible name, default `Breadcrumb`; localized hosts pass their own.
   */
  label?: string
  /**
   * Above this count, shows the first crumb, overflow and last two; `Infinity` disables it.
   */
  maxItems?: number
  /**
   * The app's router, for every crumb with an `href` (`link.md` §Routing): a click that would
   * navigate this tab, and a crumb chosen from the overflow, call it in place of the browser.
   */
  onNavigate?: (href: string) => void
  /**
   * The overflow control's accessible name, default `Show path`.
   */
  overflowLabel?: string
}
</script>

<script lang="ts">
let {
  defaultOpen,
  items,
  label: labelOwn = 'Breadcrumb',
  maxItems = 4,
  onNavigate,
  overflowLabel = 'Show path',
}: BreadcrumbsProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get navigate() {
    return onNavigate !== undefined
  },
}
let root = $state<HTMLElement | null>(null)
const collapsed = $derived(items.length > maxItems)
const row = $derived(collapsed ? [...items.slice(0, 1), null, ...items.slice(1).slice(-2)] : items)
const last = $derived(row.length - 1)
const hidden = $derived(
  collapsed
    ? items.slice(1, -2).map((item) => ({
        label: item.label,
        onSelect: () => {
          if (item.onSelect) item.onSelect()
          else if (item.href !== undefined) {
            if (listening.navigate) onNavigate?.(item.href)
            else window.location.assign(item.href)
          }
        },
      }))
    : [],
)
const navigatesHere = $derived(
  (event: MouseEvent): boolean =>
    !event.defaultPrevented &&
    event.button === 0 &&
    !event.metaKey &&
    !event.ctrlKey &&
    !event.shiftKey &&
    !event.altKey,
)
const route = $derived((event: MouseEvent, href: string | undefined): void => {
  if (href === undefined || !listening.navigate || !navigatesHere(event)) return
  event.preventDefault()
  onNavigate?.(href)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Breadcrumbs',
    element: () => root,
    state: () => ({
      items: items
        .filter((item, at) => items.findIndex((other) => other.label === item.label) === at)
        .map((item) => ({
          id: item.label,
          label: item.label,
          ...(item === items[items.length - 1] ||
          (item.href === undefined && item.onSelect === undefined)
            ? { disabled: true }
            : {}),
        })),
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          (() => {
            const item = items.find((candidate) => candidate.label === value)
            if (item === undefined) return
            const shown = row.indexOf(item)
            if (shown === -1) hidden.find((entry) => entry.label === value)?.onSelect()
            else
              agentPress(
                root?.querySelectorAll(':scope > ol > li')[shown]?.querySelector('a, button'),
              )
          })(),
      },
    },
    withholds: () => (hidden.length === 0 ? null : root?.querySelectorAll(':scope > ol > li')[1]),
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<nav bind:this={root} class={styles.nav} aria-label={label} data-member="breadcrumbs"
    ><ol class={styles.list}
      >{#each row as rung, at (rung === null ? 'overflow' : `${at}-${rung.label}`)
        }<li class={styles.item}
          >{#if rung === null
            }{#snippet triggerOfMenu1()
              }<Button
                variant="ghost"
                tone="neutral"
                size="sm"
                iconOnly={true}
                icon="overflow"
                label={overflowLabel}
            />{/snippet
            }<Menu {defaultOpen} items={hidden} trigger={triggerOfMenu1}
          />{:else if at === last
            }<span class={styles.crumb} aria-current="page">{rung.label}</span
          >{:else if rung.href !== undefined
            }<a
              class={styles.crumb}
              href={rung.href}
              onclick={(event) => { (rung.onSelect?.(), route(event, rung.href)) }}
              >{rung.label
            }</a
          >{:else if rung.onSelect !== undefined
            }<button class={styles.crumb} type="button" onclick={() => { rung.onSelect?.() }}
              >{rung.label
            }</button
          >{:else
            }<span class={styles.crumb}>{rung.label}</span
          >{/if
          }{#if at !== last}<span class={styles.separator}><Icon name="next" size="sm" /></span>{/if
        }</li
      >{/each
    }</ol
  ></nav
>{/if
}{@render joined.end?.()}
